26	  const badge = h('span', { class: 'badge running' }, 'connecting…');
27	  const cancelBtn = h('button', { class: 'danger small', style: { display: 'none' }, onclick: async () => {
28	    cancelBtn.disabled = true;
29	    try { await api.cancelRun(runId); } catch { cancelBtn.disabled = false; }
30	  } }, 'Cancel run');
31	  const workloadNote = h('span', { class: 'progress-note' });
32	  const levelsStrip = h('div', { class: 'levels-strip' });
33	  const banners = h('div');
34	  const tiles = h('div', { class: 'tiles' });
35	  const chartsBox = h('div');
36	  const resultsBox = h('div');
37	
38	  app.append(
39	    h('div', { class: 'run-head' },
40	      h('h1', {}, `Run ${runId}`), badge, workloadNote, h('span', { class: 'spacer' }), cancelBtn),
41	    banners, levelsStrip, tiles, chartsBox, resultsBox);
42	
43	  const warned = sessionStorage.getItem(`fm-warn-${runId}`);
44	  if (warned) {
45	    for (const wtext of JSON.parse(warned)) banners.append(h('div', { class: 'banner warn' }, '⚠ ' + wtext));
46	  }
47	
48	  // --- charts are built once targets are known (hello) ---
49	  function buildCharts(targets) {
50	    const isClone = state.strategy === 'clone';
51	    const isSession = state.strategy === 'session';
52	    const bands = () => state.warmups;
53	
54	    const mk = (title, note, opts) => {
55	      const el = h('div');
56	      const head = h('div', { class: 'chart-head' }, h('h2', {}, title), note ? h('span', { class: 'u-note' }, note) : null);
57	      const card = h('div', { class: 'card chart-card' }, head, el);
58	      chartsBox.append(card);
59	      return { el, head, chart: timeChart(el, opts) };
60	    };
61	
62	    const tputSeries = targets.map((t) => ({ label: t.name, color: targetColor(t.id) }));
63	    if (isSession) {
64	      for (const t of targets) tputSeries.push({ label: `${t.name} clones`, color: targetColor(t.id), dash: [5, 5] });
65	    }
66	    charts.tput = mk(isClone ? 'Clone throughput' : 'Push throughput',
67	      isClone ? 'successful clones per second' : 'successful pushes per second' + (isSession ? ' · dashed = clones/s' : ''),
68	      { series: tputSeries, unit: fmtNum, bands }).chart;
69	
70	    const latHead = mk('Latency', `rolling 10s window · shaded = warm-up`, {
71	      series: targets.map((t) => ({ label: t.name, color: targetColor(t.id) })),
72	      unit: fmtMs, bands,
73	    });
74	    charts.lat = latHead.chart;
75	    const seg = h('div', { class: 'seg' }, ['p50', 'p95', 'p99'].map((p) =>
76	      h('button', { type: 'button', class: p === pct ? 'on' : '', onclick: (ev) => {
77	        pct = p;
78	        for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.textContent === p);
79	        refeedLatency();
80	      } }, p)));
81	    latHead.head.append(seg);
82	
83	    const errSeries = [];
84	    for (const t of targets) errSeries.push({ label: `${t.name} err`, color: targetColor(t.id) });
85	    for (const t of targets) errSeries.push({ label: `${t.name} cas`, color: targetColor(t.id), dash: [5, 5] });
86	    charts.err = mk('Errors & contention', 'failures/s (solid) and CAS rejections/s (dashed)',
87	      { series: errSeries, unit: fmtNum, bands }).chart;
88	  }
89	
90	  function refeedLatency() {
91	    if (!charts.lat) return;
92	    charts.lat.setAll(state.latRows.map((r) => [r.ts, ...r.vals.map((v) => (v ? v[pct] : null))]));
93	  }
94	
95	  function buildTiles(targets) {
96	    tiles.innerHTML = '';
97	    for (const t of targets) {
98	      state.totals[t.id] = { ok: 0, cas: 0, err: 0, lastOps: 0, p95: 0 };
99	      t._tile = {
100	        ops: h('b', {}, '–'), p95: h('b', {}, '–'), errs: h('b', {}, '0'),
101	        label: h('div', { class: 'tlabel' }, t.remote),
102	        err: h('div', { class: 'terr', style: { display: 'none' } }),
103	        root: null,
104	      };
105	      t._tile.root = h('div', { class: 'tile', style: { '--tcolor': targetColor(t.id) } },
106	        h('div', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id) } }), t.name),
107	        t._tile.label,
108	        h('div', { class: 'stats' },
109	          h('div', { class: 'stat' }, t._tile.ops, h('span', {}, 'ops/s')),
110	          h('div', { class: 'stat' }, t._tile.p95, h('span', {}, 'p95 (10s)')),
111	          h('div', { class: 'stat' }, t._tile.errs, h('span', {}, 'errors'))),
112	        t._tile.err);
113	      tiles.append(t._tile.root);
114	    }
115	  }
116	
117	  function renderLevels() {
118	    levelsStrip.innerHTML = '';
119	    const levels = state.hello ? state.hello.levels : [];
120	    const curIdx = state.curLevel ? state.curLevel.level_index : -1;
121	    levels.forEach((c, i) => {
122	      const cls = state.done || i < curIdx ? 'done' : i === curIdx ? 'current' : '';
123	      levelsStrip.append(h('span', { class: `level-chip ${cls}` }, `c=${c}`));
124	    });
125	    levelsStrip.append(progressBar, progressNote);
126	  }
127	  const progressBar = h('div', { class: 'progress' }, h('div', { style: { width: '0%' } }));
128	  const progressNote = h('span', { class: 'progress-note' });
129	
130	  function tickProgress() {
131	    if (!state.curLevel || state.done) { progressBar.firstChild.style.width = state.done ? '100%' : '0%'; return; }
132	    const l = state.curLevel;
133	    const t0 = Date.parse(l.at) / 1000;
134	    const total = l.warmup_sec + l.duration_sec;
135	    const elapsed = Math.min(Date.now() / 1000 - t0, total);
136	    progressBar.firstChild.style.width = `${(elapsed / total) * 100}%`;
137	    const remain = Math.max(0, Math.round(total - elapsed));
138	    progressNote.textContent = elapsed < l.warmup_sec
139	      ? `level ${l.level_index + 1}: warming up · ${remain}s left`
140	      : `level ${l.level_index + 1}: measuring · ${remain}s left`;
141	  }
142	
143	  // --- results table ---
144	  const resultCols = [
145	    ['c', (r) => r.concurrency], ['ok', (r) => r.ok], ['ops/s', (r) => r.ops_per_sec.toFixed(1)],
146	    ['p50', (r) => fmtMs(r.p50_ms)], ['p95', (r) => fmtMs(r.p95_ms)], ['p99', (r) => fmtMs(r.p99_ms)],
147	    ['p99.9', (r) => fmtMs(r.p999_ms)], ['max', (r) => fmtMs(r.max_ms)],
148	    ['cas', (r) => r.cas_failures], ['err', (r) => r.other_errors],
149	  ];
150	  let resultsTable = null;
151	  function appendLevelResult(ev) {
152	    if (!resultsTable) {
153	      resultsTable = h('table', { class: 'results' },
154	        h('thead', {}, h('tr', {}, h('th', {}, 'target'), resultCols.map(([name]) => h('th', {}, name)))),
155	        h('tbody'));
156	      resultsBox.append(h('div', { class: 'card' }, h('h2', {}, 'Level results'), resultsTable));
157	    }
158	    const tbody = resultsTable.querySelector('tbody');
159	    let first = true;
160	    for (const t of state.hello.targets) {
161	      const r = ev.targets[String(t.id)];
162	      if (!r) continue;
163	      tbody.append(h('tr', { class: first ? 'lvl-first' : '' },
164	        h('td', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id), marginRight: '6px' } }), t.name),
165	        resultCols.map(([, fn], ci) => h('td', { class: ci >= 8 && fn(r) > 0 ? 'num-bad' : '' }, String(fn(r))))));
166	      first = false;
167	    }
168	  }
169	
170	  // --- event handlers ---
171	  const handlers = {
172	    hello(ev) {
173	      state.hello = ev;
174	      state.strategy = ev.workload.strategy;
175	      workloadNote.textContent = `${ev.workload.strategy} · sweep ${ev.levels.join(', ')} · ${ev.workload.duration_sec}s/level`;
176	      buildTiles(ev.targets);
177	      buildCharts(ev.targets);
178	      renderLevels();
179	      cancelBtn.style.display = '';
180	      badge.className = 'badge running';
181	      badge.textContent = 'running';
182	    },
183	    target_ready(ev) {
184	      const t = state.hello?.targets.find((x) => x.id === ev.target);
185	      if (t && t._tile) t._tile.label.textContent = `${ev.label} · ${ev.object_format}${ev.nodes > 1 ? ` · ${ev.nodes} nodes` : ''}`;
186	    },
187	    level_start(ev) {
188	      state.curLevel = ev;
189	      const t0 = Date.parse(ev.at) / 1000;
190	      state.warmups.push({ from: t0, to: t0 + ev.warmup_sec });
191	      renderLevels();
192	    },
193	    bucket(ev) {
194	      if (!state.hello) return;
195	      const targets = state.hello.targets;
196	      const isClone = state.strategy === 'clone';
197	      const vals = targets.map((t) => ev.targets[String(t.id)] || null);
198	
199	      // throughput (+ dashed clone series for session)
200	      const tputVals = vals.map((v) => (v ? (isClone ? v.clone_ok || 0 : v.ok) : null));
201	      if (state.strategy === 'session') tputVals.push(...vals.map((v) => (v ? v.clone_ok || 0 : null)));
202	      charts.tput.push(ev.t, tputVals);
203	
204	      // latency rows retained for percentile switching
205	      const latVals = vals.map((v) => v && (isClone ? v.clone_ok : v.ok) > 0
206	        ? (isClone
207	          ? { p50: v.clone_p50_ms, p95: v.clone_p95_ms, p99: v.clone_p99_ms }
208	          : { p50: v.p50_ms, p95: v.p95_ms, p99: v.p99_ms })
209	        : null);
210	      state.latRows.push({ ts: ev.t, vals: latVals });
211	      charts.lat.push(ev.t, latVals.map((v) => (v ? v[pct] : null)));
212	
213	      charts.err.push(ev.t, [
214	        ...vals.map((v) => (v ? (isClone ? v.clone_err || 0 : v.err) : null)),
215	        ...vals.map((v) => (v ? v.cas : null)),
216	      ]);
217	
218	      // tiles
219	      targets.forEach((t, i) => {
220	        const v = vals[i];
221	        if (!v || !t._tile) return;
222	        const tot = state.totals[t.id];
223	        tot.ok += isClone ? v.clone_ok || 0 : v.ok;
224	        tot.err += (isClone ? v.clone_err || 0 : v.err);
225	        tot.cas += v.cas || 0;
226	        t._tile.ops.textContent = fmtNum(isClone ? v.clone_ok || 0 : v.ok);
227	        t._tile.p95.textContent = fmtMs(latVals[i] ? latVals[i].p95 : null) || '–';
228	        t._tile.errs.textContent = fmtNum(tot.err + tot.cas);
229	        t._tile.errs.style.color = tot.err + tot.cas > 0 ? 'var(--critical)' : '';
230	      });
231	    },
232	    level_result(ev) { appendLevelResult(ev); },
233	    target_error(ev) {
234	      banners.append(h('div', { class: 'banner error' },
235	        `✖ ${targetName(ev.target)}: ${ev.message}${ev.fatal ? ' — target removed from the run' : ''}`));
236	      const t = state.hello?.targets.find((x) => x.id === ev.target);
237	      if (t && t._tile && ev.fatal) {
238	        t._tile.root.classList.add('dead');
239	        t._tile.err.style.display = '';
240	        t._tile.err.textContent = ev.message;
241	      }
242	    },
243	    run_done(ev) {
244	      state.done = ev;
245	      badge.className = `badge ${ev.state}`;
246	      badge.textContent = ev.state;
247	      cancelBtn.style.display = 'none';
248	      renderLevels();
249	      tickProgress();
250	      if (ev.results_file) {
251	        banners.append(h('div', { class: 'banner' },
252	          'Results saved to ', h('code', {}, ev.results_file), ' — ',
253	          h('a', { href: `#history/${ev.results_file}`, style: { color: 'var(--accent)' } }, 'compare in history')));
254	      }
255	      if (es) { es.close(); es = null; }
256	    },
257	  };
258	
259	  function targetName(id) {
260	    const t = state.hello?.targets.find((x) => x.id === id);
261	    return t ? t.name : (id < 0 ? 'run' : `target ${id}`);
262	  }
263	
264	  es = openRunStream(runId, handlers);
265	  es.onerror = () => { if (!state.done) { badge.className = 'badge'; badge.textContent = 'reconnecting…'; } };
266	  es.onopen = () => { if (!state.done && state.hello) { badge.className = 'badge running'; badge.textContent = 'running'; } };
267	  ticker = setInterval(tickProgress, 500);
268	
269	  return () => {
270	    if (es) es.close();
271	    clearInterval(ticker);
272	    Object.values(charts).forEach((c) => c.destroy && c.destroy());
273	  };
274	}
