// Push race: the demo view. Same SSE stream as the dashboard, rendered as a
// live head-to-head — huge cumulative counters, rolling rates, and lanes that
// stretch toward the leader. State derives entirely from the event stream, so
// a finished run replays straight to its final standings.

import { h } from '../dom.js';
import { openRunStream } from '../sse.js';
import { targetColor, fmtMs } from '../charts.js';

const fmtInt = (n) => n.toLocaleString('en-US');

export function renderRace(app, runId) {
  const state = {
    hello: null,
    curLevel: null,
    done: null,
    lanes: {},       // target id → {total, rates: [last 5 bucket ok], els}
    finals: {},      // target id → last level_result row (measured ops/s)
  };
  let es = null;
  let ticker = null;

  const badge = h('span', { class: 'badge running' }, 'connecting…');
  const clock = h('div', { class: 'race-clock' }, '–:––');
  const phase = h('div', { class: 'race-phase' }, '');
  const banners = h('div');
  const lanesBox = h('div', { class: 'race-lanes' });
  const finishBox = h('div');

  app.append(
    h('div', { class: 'race-head' },
      h('h1', {}, '⚡ Push race'),
      badge,
      h('span', { class: 'spacer' }),
      h('a', { class: 'race-alt', href: `#run/${runId}` }, '📊 full dashboard')),
    h('div', { class: 'race-timer' }, clock, phase),
    banners, lanesBox, finishBox);

  function buildLanes(targets) {
    lanesBox.innerHTML = '';
    for (const t of targets) {
      const els = {
        total: h('div', { class: 'race-total' }, '0'),
        rate: h('div', { class: 'race-rate' }, '– pushes/s'),
        bar: h('div', { class: 'race-bar', style: { '--tcolor': targetColor(t.id), width: '2%' } }),
        crown: h('span', { class: 'race-crown' }, ''),
        note: h('div', { class: 'race-note' }, t.remote),
      };
      const lane = h('div', { class: 'race-lane', style: { '--tcolor': targetColor(t.id) } },
        h('div', { class: 'race-lane-head' },
          h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id) } }),
          h('span', { class: 'race-name' }, t.name), els.crown,
          h('span', { class: 'spacer' }), els.rate),
        h('div', { class: 'race-track' }, els.bar, h('span', { class: 'race-flag' }, '🏁')),
        h('div', { class: 'race-lane-foot' }, els.total, h('span', { class: 'race-unit' }, 'pushes'), els.note));
      state.lanes[t.id] = { total: 0, rates: [], els, lane };
      lanesBox.append(lane);
    }
  }

  function updateLanes() {
    const lanes = Object.values(state.lanes);
    const leader = Math.max(1, ...lanes.map((l) => l.total));
    for (const l of lanes) {
      l.els.total.textContent = fmtInt(l.total);
      l.els.bar.style.width = `${Math.max(2, (l.total / leader) * 100)}%`;
      const avg = l.rates.length ? l.rates.reduce((a, b) => a + b, 0) / l.rates.length : 0;
      l.els.rate.textContent = `${avg >= 10 ? Math.round(avg) : avg.toFixed(1)} pushes/s`;
      l.els.crown.textContent = lanes.length > 1 && l.total === leader && l.total > 0 ? '👑' : '';
    }
  }

  function tickClock() {
    if (state.done) return;
    if (!state.curLevel) { clock.textContent = '–:––'; return; }
    const l = state.curLevel;
    const t0 = Date.parse(l.at) / 1000;
    const total = l.warmup_sec + l.duration_sec;
    const elapsed = Math.min(Date.now() / 1000 - t0, total);
    const remain = Math.max(0, Math.ceil(total - elapsed));
    clock.textContent = `${Math.floor(remain / 60)}:${String(remain % 60).padStart(2, '0')}`;
    phase.textContent = elapsed < l.warmup_sec ? 'warming up' : `c=${l.concurrency} · racing`;
  }

  function finish(ev) {
    clock.textContent = '0:00';
    phase.textContent = 'finished';
    const rows = (state.hello ? state.hello.targets : [])
      .map((t) => ({ t, total: state.lanes[t.id]?.total || 0, final: state.finals[t.id] }))
      .sort((a, b) => b.total - a.total);
    if (!rows.length || rows[0].total === 0) return;

    const [win, ...rest] = rows;
    const podium = h('div', { class: 'race-podium card' },
      h('div', { class: 'race-winner' },
        '🏆 ', h('b', { style: { color: targetColor(win.t.id) } }, win.t.name), ' wins',
        rest.length && rest[0].total > 0
          ? ` — ${(win.total / rest[0].total).toFixed(1)}× more pushes`
          : ''),
      h('table', { class: 'results' },
        h('thead', {}, h('tr', {}, h('th', {}, ''), h('th', {}, 'target'), h('th', {}, 'pushes'),
          h('th', {}, 'pushes/s'), h('th', {}, 'p50'), h('th', {}, 'p95'))),
        h('tbody', {}, rows.map((r, i) => h('tr', {},
          h('td', {}, ['🥇', '🥈', '🥉'][i] || ''),
          h('td', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(r.t.id), marginRight: '6px' } }), r.t.name),
          h('td', {}, fmtInt(r.total)),
          h('td', {}, r.final ? r.final.ops_per_sec.toFixed(1) : '–'),
          h('td', {}, r.final ? fmtMs(r.final.p50_ms) : '–'),
          h('td', {}, r.final ? fmtMs(r.final.p95_ms) : '–'))))));
    finishBox.append(podium);
    if (ev.results_file) {
      finishBox.append(h('div', { class: 'banner' },
        'Results saved to ', h('code', {}, ev.results_file), ' — ',
        h('a', { href: `#history/${ev.results_file}`, style: { color: 'var(--accent)' } }, 'compare in history')));
    }
  }

  const handlers = {
    hello(ev) {
      state.hello = ev;
      buildLanes(ev.targets);
      badge.className = 'badge running';
      badge.textContent = 'running';
    },
    level_start(ev) { state.curLevel = ev; },
    bucket(ev) {
      if (!state.hello) return;
      for (const t of state.hello.targets) {
        const v = ev.targets[String(t.id)];
        const l = state.lanes[t.id];
        if (!v || !l) continue;
        l.total += v.ok;
        l.rates.push(v.ok);
        if (l.rates.length > 5) l.rates.shift();
        if (v.ok > 0) {
          l.els.total.classList.remove('pop');
          void l.els.total.offsetWidth; // restart the pop animation
          l.els.total.classList.add('pop');
        }
      }
      updateLanes();
    },
    level_result(ev) {
      for (const [id, r] of Object.entries(ev.targets)) state.finals[id] = r;
    },
    target_error(ev) {
      const t = state.hello?.targets.find((x) => x.id === ev.target);
      banners.append(h('div', { class: 'banner error' },
        `✖ ${t ? t.name : `target ${ev.target}`}: ${ev.message}${ev.fatal ? ' — out of the race' : ''}`));
      if (t && ev.fatal) state.lanes[t.id]?.lane.classList.add('dead');
    },
    run_done(ev) {
      state.done = ev;
      badge.className = `badge ${ev.state}`;
      badge.textContent = ev.state;
      finish(ev);
      if (es) { es.close(); es = null; }
    },
  };

  es = openRunStream(runId, handlers);
  es.onerror = () => { if (!state.done) { badge.className = 'badge'; badge.textContent = 'reconnecting…'; } };
  ticker = setInterval(tickClock, 250);

  return () => {
    if (es) es.close();
    clearInterval(ticker);
  };
}

