8	const strategies = [
9	  ['branch', 'branch — one repo, per-agent branches (headline write number)'],
10	  ['repo', 'repo — agents spread across N repos (horizontal scale)'],
11	  ['clone', 'clone — shallow-clone loop (read-side ceiling)'],
12	  ['session', 'session — clone + push checkpoints per session (agent lifecycle)'],
13	];
14	
15	let targetSeq = 0;
16	
17	function blankTarget() {
18	  return { key: ++targetSeq, name: '', remote: '', repos: '', user: '', secret: '', insecure: false, object_format: 'auto', token_url: '', jurisdiction: '', client_id: '' };
19	}
20	
21	export function renderNewRun(app) {
