24	
25	  const targetsBox = h('div');
26	  const startBtn = h('button', { class: 'primary', type: 'submit', disabled: true }, 'Start benchmark');
27	  const confirm = h('input', { type: 'checkbox', id: 'confirm', onchange: () => { startBtn.disabled = !confirm.checked; } });
28	
29	  function field(label, input, cls = '') {
30	    return h('div', { class: `field ${cls}` }, h('label', {}, label), input);
31	  }
32	  const inp = (attrs) => h('input', { type: 'text', ...attrs });
33	
34	  // --- workload inputs (queried on submit) ---
35	  const w = {
36	    strategy: h('select', { onchange: () => syncStrategy() }, strategies.map(([v, t]) => h('option', { value: v }, t))),
37	    concurrency: inp({ value: '1,8,32', placeholder: 'e.g. 1,8,32,128' }),
38	    duration_sec: inp({ value: '60' }),
39	    warmup_sec: inp({ value: '10' }),
40	    files_min: inp({ value: '1' }),
41	    files_max: inp({ value: '10' }),
42	    file_size: inp({ value: '2048' }),
