59	    const s = w.strategy.value;
60	    commitFields.style.display = s === 'clone' ? 'none' : '';
61	    cloneFields.style.display = (s === 'clone' || s === 'session') ? '' : 'none';
62	    w.session_commits.parentElement.style.display = s === 'session' ? '' : 'none';
63	  }
64	
