209	// start validates a request and launches its coordinator. It returns
210	// user-facing warnings (e.g. the github.com abuse note) alongside the run.
211	func (m *RunManager) start(req startRequest) (*Run, []string, error) {
212		if !req.ConfirmAuthorized {
213			return nil, nil, errors.New("confirm_authorized must be true: only benchmark infrastructure you own or are explicitly authorized to load-test")
214		}
215		if len(req.Targets) == 0 {
216			return nil, nil, errors.New("at least one target is required")
217		}
218		if len(req.Targets) > maxTargets {
219			return nil, nil, fmt.Errorf("at most %d targets per run", maxTargets)
220		}
221	
222		ws := req.Workload.withDefaults()
223		runID := bench.NewRunID()
224		bw := ws.toWorkload(runID)
225		if err := bw.Validate(); err != nil {
226			return nil, nil, err
227		}
228	
229		var warnings []string
230		targets := make([]*targetState, len(req.Targets))
231		for i, ts := range req.Targets {
232			bt := ts.toTarget()
233			name := ts.Name
234			if name == "" {
235				name = defaultTargetName(bt.Remote, i)
236			}
237			if bench.IsGitHubDotCom(bt.Remote) {
238				if hi := slices.Max(bw.Concurrency); hi > 16 {
239					warnings = append(warnings, fmt.Sprintf(
240						"concurrency %d against github.com is likely to trip secondary rate limits / abuse detection — keep it low (e.g. 1,4)", hi))
241				}
242			}
243			targets[i] = &targetState{id: i, name: name, spec: bt, col: &collector{}}
244		}
245	
246		ctx, cancel := context.WithCancel(context.Background())
247		run := &Run{
248			ID: runID, StartedAt: time.Now(), log: newEventLog(),
249			ctx: ctx, cancel: cancel,
250			workload: ws, bw: bw, state: "starting", targets: targets,
251		}
252	
253		m.mu.Lock()
254		if m.active != nil {
255			m.mu.Unlock()
256			cancel()
257			return nil, nil, errRunActive
258		}
259		m.active = run
260		m.runs[run.ID] = run
261		m.order = append(m.order, run.ID)
262		m.pruneLocked()
263		m.mu.Unlock()
264	
265		run.log.emit("hello", run.helloEvent())
266		go run.coordinate(m)
267		return run, warnings, nil
268	}
