// CLI-sourced credentials and target discovery. The GUI is a loopback control
// panel on the operator's own machine, so instead of pasting a token into the
// form, a target can name a secret_source ("gh" | "entire") and the server
// pulls the credential from the operator's already-authenticated CLI at run
// start. The token then never appears in any request or response body, and
// the browser never holds it at all.

package server

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os/exec"
	"strings"
	"sync"
	"time"
)

const cliTimeout = 15 * time.Second

// secretSources maps a TargetSpec.SecretSource to the fixed argv that prints
// the credential. Nothing user-controlled is ever executed: an unknown source
// is an error, never a command.
var secretSources = map[string][]string{
	"gh":     {"gh", "auth", "token"},
	"entire": {"entire", "auth", "token"},
}

func resolveSecretSource(source string) (string, error) {
	argv, ok := secretSources[source]
	if !ok {
		return "", fmt.Errorf("unknown secret_source %q (gh | entire)", source)
	}
	out, err := runCLI(argv...)
	if err != nil {
		return "", err
	}
	if out == "" {
		return "", fmt.Errorf("%s printed an empty token", strings.Join(argv, " "))
	}
	return out, nil
}

func runCLI(argv ...string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), cliTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, argv[0], argv[1:]...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg == "" {
			msg = err.Error()
		}
		if i := strings.IndexByte(msg, '\n'); i >= 0 {
			msg = msg[:i]
		}
		return "", fmt.Errorf("%s: %s (is it installed and logged in?)", strings.Join(argv, " "), msg)
	}
	return strings.TrimSpace(stdout.String()), nil
}

// suggestEntry is one CLI-discovered target template: a ready-to-post
// TargetSpec with SecretSource set and Secret empty, or the reason discovery
// failed. Note flags anything the operator still has to ensure themselves.
type suggestEntry struct {
	Target *TargetSpec `json:"target,omitempty"`
	Note   string      `json:"note,omitempty"`
	Error  string      `json:"error,omitempty"`
}

// handleLocalSuggest builds target templates from the operator's gh and
// entire CLI logins. It runs the same discovery scripts/compare-local.sh
// does: GitHub login → conventional throwaway repo; entire auth context →
// jurisdiction endpoints + default cluster + conventional native repo.
func (s *Server) handleLocalSuggest(w http.ResponseWriter, _ *http.Request) {
	var gh, entire suggestEntry
	var wg sync.WaitGroup
	wg.Add(2)
	go func() { defer wg.Done(); gh = suggestGitHub() }()
	go func() { defer wg.Done(); entire = suggestEntire() }()
	wg.Wait()
	writeJSON(w, http.StatusOK, map[string]suggestEntry{"github": gh, "entire": entire})
}

func suggestGitHub() suggestEntry {
	login, err := runCLI("gh", "api", "user", "--jq", ".login")
	if err != nil {
		return suggestEntry{Error: err.Error()}
	}
	repo := login + "/forgemark-target"
	return suggestEntry{
		Target: &TargetSpec{
			Name:         "github",
			Remote:       "https://github.com",
			Repos:        []string{repo},
			SecretSource: "gh",
		},
		Note: fmt.Sprintf("repo %s must exist — scripts/compare-local.sh provisions it", repo),
	}
}

func suggestEntire() suggestEntry {
	status, err := runCLI("entire", "auth", "status")
	if err != nil {
		return suggestEntry{Error: err.Error()}
	}
	slug := statusField(status, "Jurisdiction:")
	loginHost := statusField(status, "Context:")
	handle := strings.TrimPrefix(statusField(status, "User:"), "@")
	if slug == "" || loginHost == "" {
		return suggestEntry{Error: "could not parse `entire auth status` output"}
	}
	baseDomain := loginHost
	if i := strings.Index(loginHost, ".auth."); i >= 0 {
		baseDomain = loginHost[i+len(".auth."):]
	}

	clustersJSON, err := runCLI("entire", "api", "/api/v1/clusters")
	if err != nil {
		return suggestEntry{Error: err.Error()}
	}
	var doc struct {
		Clusters []struct {
			Jurisdiction string `json:"jurisdiction"`
			PublicURL    string `json:"publicUrl"`
			IsDefault    bool   `json:"isDefault"`
		} `json:"clusters"`
	}
	if err := json.Unmarshal([]byte(clustersJSON), &doc); err != nil {
		return suggestEntry{Error: fmt.Sprintf("decode clusters: %v", err)}
	}
	remote := ""
	for _, c := range doc.Clusters {
		if c.Jurisdiction == slug && (remote == "" || c.IsDefault) {
			remote = c.PublicURL
		}
	}
	if remote == "" {
		return suggestEntry{Error: fmt.Sprintf("no cluster in jurisdiction %q", slug)}
	}

	repo := fmt.Sprintf("et/forgemark-%s/forgemark-target", handle)
	return suggestEntry{
		Target: &TargetSpec{
			Name:         "entire-" + slug,
			Remote:       remote,
			Repos:        []string{repo},
			TokenURL:     "https://" + loginHost + "/oauth/token",
			Jurisdiction: "https://" + slug + "." + baseDomain,
			SecretSource: "entire",
		},
		Note: fmt.Sprintf("repo %s must exist — FM_ENTIRE_NATIVE=1 scripts/compare-local.sh provisions it", repo),
	}
}

// statusField pulls the value after a "Label:" line prefix from the
// key-value block `entire auth status` prints.
func statusField(status, label string) string {
	for _, line := range strings.Split(status, "\n") {
		line = strings.TrimSpace(line)
		if rest, ok := strings.CutPrefix(line, label); ok {
			return strings.Fields(rest + " ")[0]
		}
	}
	return ""
}

