300	func (m *RunManager) clearActive(r *Run) {
301		m.mu.Lock()
302		defer m.mu.Unlock()
303		if m.active == r {
304			m.active = nil
305		}
306	}
307	
308	// coordinate is the run's driver goroutine: build runners, then walk the
309	// concurrency sweep with a barrier per level so every target starts each
310	// level at the same instant (the whole point of a comparison run).
311	func (r *Run) coordinate(m *RunManager) {
312		defer r.cancel()
313	
314		// Resolve every target concurrently — entiredb setup probes the cluster.
315		// A target that fails setup is dead but doesn't kill the comparison.
316		var wg sync.WaitGroup
317		for _, t := range r.targets {
318			wg.Add(1)
319			go func(t *targetState) {
320				defer wg.Done()
321				var (
322					lr  levelRunner
323					err error
324				)
325				if isDemoRemote(t.spec.Remote) {
326					lr, err = newDemoRunner(t.spec.Remote, r.bw, t.col)
327				} else {
328					lr, err = bench.NewRunner(r.ctx, t.spec, r.bw, t.col)
329				}
330				t.spec.Secret = "" // consumed; nothing on the run retains it
331				if err != nil {
332					r.markDead(t, -1, err)
333					return
334				}
335				r.mu.Lock()
336				t.runner = lr
337				t.label = lr.Label()
338				r.mu.Unlock()
339				r.log.emit("target_ready", map[string]any{
340					"target": t.id, "label": lr.Label(), "nodes": lr.Nodes(), "object_format": lr.ObjectFormat(),
341				})
342			}(t)
343		}
344		wg.Wait()
345	
346		if r.aliveTargets() == nil {
347			r.finish(m, "failed")
348			return
349		}
350		r.setState("running")
351	
352		// One ticker per run: a single bucket event per second carries every
353		// target's stats, so chart columns align by construction.
354		tickerDone := make(chan struct{})
355		tickerStopped := make(chan struct{})
356		go func() {
357			defer close(tickerStopped)
358			tick := time.NewTicker(time.Second)
359			defer tick.Stop()
360			for {
361				select {
362				case <-tick.C:
363					r.emitBucket()
364				case <-tickerDone:
365					return
366				}
367			}
368		}()
369	
370		for li, c := range r.bw.Concurrency {
371			if r.ctx.Err() != nil || r.aliveTargets() == nil {
372				break
373			}
374			r.mu.Lock()
375			r.levelIdx = li
376			r.levelConc = c
377			r.mu.Unlock()
378			r.log.emit("level_start", map[string]any{
379				"level_index": li, "concurrency": c,
380				"warmup_sec": r.bw.Warmup.Seconds(), "duration_sec": r.bw.Duration.Seconds(),
381				"at": time.Now().UTC(),
382			})
383	
384			var lwg sync.WaitGroup
385			for _, t := range r.aliveTargets() {
386				lwg.Add(1)
387				go func(t *targetState) {
388					defer lwg.Done()
389					t.col.reset()
390					res, err := t.runner.RunLevel(r.ctx, c)
391					if err != nil {
392						r.markDead(t, li, err)
393						return
394					}
395					r.mu.Lock()
396					t.results = append(t.results, res)
397					r.mu.Unlock()
398				}(t)
399			}
400			lwg.Wait()
401	
402			results := map[string]bench.LevelResult{}
403			r.mu.Lock()
404			for _, t := range r.targets {
405				if len(t.results) > li {
406					results[strconv.Itoa(t.id)] = t.results[li]
407				}
408			}
409			r.mu.Unlock()
410			r.log.emit("level_result", map[string]any{
411				"level_index": li, "concurrency": c, "targets": results,
412			})
413		}
414	
415		close(tickerDone)
416		<-tickerStopped
417	
418		state := "done"
419		if r.ctx.Err() != nil {
420			state = "cancelled"
421		} else if r.aliveTargets() == nil {
422			state = "failed"
423		}
424		r.finish(m, state)
425	}
426	
427	func (r *Run) finish(m *RunManager, state string) {
428		r.setState(state)
429		resultsFile := r.persistResults(m.resultsDir)
430		r.mu.Lock()
431		r.resultsFile = resultsFile
432		r.mu.Unlock()
433		r.log.emit("run_done", map[string]any{
434			"state": state, "results_file": resultsFile, "at": time.Now().UTC(),
435		})
436		r.log.close()
437		m.clearActive(r)
438	}
