1	// uPlot helpers. All charts share the dark chart chrome and the fixed
2	// categorical target palette: color follows the target index, never the
3	// series' position in a particular chart.
4	
5	export const PALETTE = [
6	  '#3987e5', '#199e70', '#c98500', '#008300',
7	  '#9085e9', '#e66767', '#d55181', '#d95926',
8	];
9	export const targetColor = (i) => PALETTE[i % PALETTE.length];
10	
11	const INK_MUTED = '#898781';
12	const GRID = '#2c2c2a';
13	const BASELINE = '#383835';
14	
15	const axisFont = '12px system-ui, sans-serif';
16	
17	function baseAxes(unitFmt) {
18	  return [
19	    {
20	      stroke: INK_MUTED, font: axisFont,
21	      grid: { stroke: GRID, width: 1 },
22	      ticks: { stroke: BASELINE, width: 1 },
23	    },
24	    {
25	      stroke: INK_MUTED, font: axisFont, size: 56,
26	      grid: { stroke: GRID, width: 1 },
27	      ticks: { show: false },
28	      values: (u, splits) => splits.map((v) => (v == null ? '' : unitFmt(v))),
29	    },
30	  ];
31	}
32	
33	export const fmtNum = (v) => {
34	  if (v == null) return '';
35	  if (v >= 1000) return (v / 1000).toFixed(1) + 'k';
36	  return v >= 100 ? v.toFixed(0) : +v.toFixed(1) + '';
37	};
38	export const fmtMs = (v) => (v == null ? '' : v >= 1000 ? (v / 1000).toFixed(1) + 's' : Math.round(v) + 'ms');
39	
40	// timeChart: a streaming time-series chart. `series` is
41	// [{label, color, dash?}] — one per plotted line. `bands()` returns
42	// [{from,to}] x-ranges (unix secs) shaded as warm-up. push()/setAll() update
43	// the data; the chart resizes with its container.
44	export function timeChart(el, { series, unit = fmtNum, height = 240, bands = () => [] }) {
45	  const data = [[], ...series.map(() => [])];
46	
47	  const opts = {
48	    width: el.clientWidth || 800,
49	    height,
50	    ms: false,
51	    cursor: { points: { size: 7 } },
52	    scales: { x: { time: true } },
53	    axes: baseAxes(unit),
54	    legend: { live: true },
55	    series: [
56	      { value: (u, ts) => (ts == null ? '' : new Date(ts * 1000).toLocaleTimeString()) },
57	      ...series.map((s) => ({
58	        label: s.label,
59	        stroke: s.color,
60	        width: 2,
61	        dash: s.dash,
62	        spanGaps: false,
63	        points: { show: false },
64	        value: (u, v) => (v == null ? '–' : unit(v)),
65	      })),
66	    ],
67	    hooks: {
68	      drawClear: [
69	        (u) => {
70	          // Warm-up shading: quieter than data, under the series.
71	          const { ctx } = u;
72	          ctx.save();
73	          ctx.fillStyle = 'rgba(137, 135, 129, 0.07)';
74	          for (const b of bands()) {
75	            const x0 = u.valToPos(b.from, 'x', true);
76	            const x1 = u.valToPos(b.to, 'x', true);
77	            ctx.fillRect(x0, u.bbox.top, x1 - x0, u.bbox.height);
78	          }
79	          ctx.restore();
80	        },
81	      ],
82	    },
83	  };
84	
85	  const u = new uPlot(opts, data, el);
