1	// CLI-sourced credentials and target discovery. The GUI is a loopback control
2	// panel on the operator's own machine, so instead of pasting a token into the
3	// form, a target can name a secret_source ("gh" | "entire") and the server
4	// pulls the credential from the operator's already-authenticated CLI at run
5	// start. The token then never appears in any request or response body, and
6	// the browser never holds it at all.
7	
8	package server
9	
10	import (
11		"bytes"
12		"context"
13		"encoding/json"
14		"fmt"
15		"net/http"
16		"os/exec"
17		"strings"
18		"sync"
