1	// CLI-sourced credentials and target discovery. The GUI is a loopback control
2	// panel on the operator's own machine, so instead of pasting a token into the
3	// form, a target can name a secret_source ("gh" | "glab" | "entire") and the
4	// server pulls the credential from the operator's already-authenticated CLI
5	// at run start. The token then never appears in any request or response body,
6	// and the browser never holds it at all.
7	
8	package server
9	
10	import (
11		"bytes"
12		"context"
13		"encoding/json"
14		"fmt"
15		"net/http"
16		"net/url"
17		"os/exec"
18		"strings"
19		"sync"
20		"time"
21	)
22	
23	const cliTimeout = 15 * time.Second
24	
25	// credSource describes how to obtain a git credential from an authenticated
26	// CLI. Two shapes cover the forges: a token printer (gh, entire — stdout is
27	// the password, the username defaults to x-access-token) and a git-credential
28	// helper (glab — fed the target host on stdin, it replies with key=value lines
29	// carrying both a username and a git-scoped password, since GitLab's stored
30	// API token often lacks repository scope). Nothing user-controlled is ever
31	// executed: an unknown source is an error, never a command.
32	type credSource struct {
33		argv    []string
34		gitCred bool // speak the git credential-helper protocol over stdin/stdout
35	}
36	
37	var secretSources = map[string]credSource{
38		"gh":     {argv: []string{"gh", "auth", "token"}},
39		"entire": {argv: []string{"entire", "auth", "token"}},
40		"glab":   {argv: []string{"glab", "auth", "git-credential", "get"}, gitCred: true},
41	}
42	
43	// resolveSecretSource returns (username, secret). username is "" when the
44	// source doesn't dictate one (the caller's default applies); it is set for
45	// git-credential helpers that name it (GitLab → oauth2). remote supplies the
46	// host a git-credential helper is queried for, so self-managed hosts work too.
47	func resolveSecretSource(source, remote string) (string, string, error) {
48		c, ok := secretSources[source]
49		if !ok {
50			return "", "", fmt.Errorf("unknown secret_source %q (gh | glab | entire)", source)
51		}
52		stdin := ""
53		if c.gitCred {
54			stdin = fmt.Sprintf("protocol=https\nhost=%s\n\n", credHost(remote))
55		}
56		out, err := runCLI(stdin, c.argv...)
57		if err != nil {
58			return "", "", err
59		}
60		if c.gitCred {
61			return parseGitCredential(out, strings.Join(c.argv, " "))
62		}
63		tok := strings.TrimSpace(out)
64		if tok == "" {
65			return "", "", fmt.Errorf("%s printed an empty token", strings.Join(c.argv, " "))
66		}
67		return "", tok, nil
68	}
69	
70	// validateSecretAudience pins a CLI-sourced credential to its issuer so the
71	// server won't materialize it for an unrelated target. A gh/glab token belongs
72	// to its forge; the entire subject token is POSTed to token_url and the
73	// resulting jurisdiction token is used across the cluster, so remote, token_url
74	// and jurisdiction must all stay under entire.io. Self-hosted forges should
75	// paste a token rather than name a CLI source.
76	func validateSecretAudience(source, remote, tokenURL, jurisdiction string) error {
77		host := func(raw string) string {
78			u, err := url.Parse(raw)
79			if err != nil {
80				return ""
81			}
82			return u.Hostname()
83		}
84		underEntire := func(h string) bool { return h == "entire.io" || strings.HasSuffix(h, ".entire.io") }
85		switch source {
86		case "gh":
87			if host(remote) != "github.com" {
88				return fmt.Errorf("secret_source gh is only valid for a github.com remote, not %q", remote)
89			}
90		case "glab":
91			if host(remote) != "gitlab.com" {
92				return fmt.Errorf("secret_source glab is only valid for a gitlab.com remote, not %q", remote)
93			}
94		case "entire":
95			for label, raw := range map[string]string{"remote": remote, "token_url": tokenURL, "jurisdiction": jurisdiction} {
96				if !underEntire(host(raw)) {
97					return fmt.Errorf("secret_source entire requires %s under entire.io, got %q", label, raw)
98				}
99			}
100		default:
101			return fmt.Errorf("unknown secret_source %q (gh | glab | entire)", source)
102		}
103		return nil
104	}
105	
106	// credHost is the host a git-credential helper should be asked about, from the
107	// target remote; it falls back to gitlab.com so a bare "glab" source works.
108	func credHost(remote string) string {
109		if u, err := url.Parse(remote); err == nil && u.Host != "" {
110			return u.Host
111		}
112		return "gitlab.com"
113	}
114	
115	// parseGitCredential extracts username/password from a credential helper's
116	// key=value reply. Only exact "username="/"password=" lines match, so sibling
117	// keys like password_expiry_utc are ignored.
118	func parseGitCredential(out, label string) (string, string, error) {
119		var user, pass string
120		for _, line := range strings.Split(out, "\n") {
121			if v, ok := strings.CutPrefix(strings.TrimSpace(line), "username="); ok {
122				user = v
123			} else if v, ok := strings.CutPrefix(strings.TrimSpace(line), "password="); ok {
124				pass = v
125			}
126		}
127		if pass == "" {
128			return "", "", fmt.Errorf("%s returned no password (is it installed and logged in?)", label)
129		}
130		return user, pass, nil
131	}
132	
133	func runCLI(stdin string, argv ...string) (string, error) {
134		ctx, cancel := context.WithTimeout(context.Background(), cliTimeout)
135		defer cancel()
136		cmd := exec.CommandContext(ctx, argv[0], argv[1:]...)
137		if stdin != "" {
138			cmd.Stdin = strings.NewReader(stdin)
139		}
140		var stdout, stderr bytes.Buffer
141		cmd.Stdout, cmd.Stderr = &stdout, &stderr
142		if err := cmd.Run(); err != nil {
143			msg := strings.TrimSpace(stderr.String())
144			if msg == "" {
145				msg = err.Error()
146			}
147			if i := strings.IndexByte(msg, '\n'); i >= 0 {
148				msg = msg[:i]
149			}
150			return "", fmt.Errorf("%s: %s (is it installed and logged in?)", strings.Join(argv, " "), msg)
151		}
152		return strings.TrimSpace(stdout.String()), nil
153	}
154	
155	// suggestEntry is one CLI-discovered target template: a ready-to-post
156	// TargetSpec with SecretSource set and Secret empty, or the reason discovery
157	// failed. Note flags anything the operator still has to ensure themselves.
158	type suggestEntry struct {
159		Target *TargetSpec `json:"target,omitempty"`
160		Note   string      `json:"note,omitempty"`
161		Error  string      `json:"error,omitempty"`
162	}
163	
164	// handleLocalSuggest builds target templates from the operator's gh, glab, and
165	// entire CLI logins, probed concurrently. Each entry is a ready-to-post target
166	// or the reason its CLI couldn't be reached; a CLI that isn't installed or
167	// logged in just yields an Error the UI shows as a dim note.
168	func (s *Server) handleLocalSuggest(w http.ResponseWriter, _ *http.Request) {
169		var gh, gitlab, entire suggestEntry
170		var wg sync.WaitGroup
171		wg.Add(3)
172		go func() { defer wg.Done(); gh = suggestGitHub() }()
173		go func() { defer wg.Done(); gitlab = suggestGitLab() }()
174		go func() { defer wg.Done(); entire = suggestEntire() }()
175		wg.Wait()
176		writeJSON(w, http.StatusOK, map[string]suggestEntry{"github": gh, "gitlab": gitlab, "entire": entire})
177	}
178	
179	func suggestGitHub() suggestEntry {
180		login, err := runCLI("", "gh", "api", "user", "--jq", ".login")
181		if err != nil {
182			return suggestEntry{Error: err.Error()}
183		}
184		repo := login + "/forgemark-target"
185		return suggestEntry{
186			Target: &TargetSpec{
187				Name:         "github",
188				Remote:       "https://github.com",
189				Repos:        []string{repo},
190				SecretSource: "gh",
191			},
192			Note: fmt.Sprintf("repo %s must exist — scripts/compare-local.sh provisions it", repo),
193		}
194	}
195	
196	func suggestGitLab() suggestEntry {
197		// glab has no --jq flag, so decode its JSON here.
198		out, err := runCLI("", "glab", "api", "user")
199		if err != nil {
200			return suggestEntry{Error: err.Error()}
201		}
202		var u struct {
203			Username string `json:"username"`
204		}
205		if err := json.Unmarshal([]byte(out), &u); err != nil {
206			return suggestEntry{Error: fmt.Sprintf("decode glab api user: %v", err)}
207		}
208		if u.Username == "" {
209			return suggestEntry{Error: "glab api user returned no username"}
210		}
211		// gitlab.com push URL is <base>/<namespace>/<project>.git. The credential
212		// (username + git-scoped password) comes from glab's credential helper at
213		// run start, so User is left blank here. The project must be created first.
214		repo := u.Username + "/forgemark-target.git"
215		return suggestEntry{
216			Target: &TargetSpec{
217				Name:         "gitlab",
218				Remote:       "https://gitlab.com",
219				Repos:        []string{repo},
220				SecretSource: "glab",
221			},
222			Note: fmt.Sprintf("project %s must exist and be pushable — create it in GitLab first", repo),
223		}
224	}
225	
226	func suggestEntire() suggestEntry {
227		// The two CLI calls are independent (the status output is only consulted
228		// after both return), so run them concurrently — each can take up to
229		// cliTimeout, and serial worst case would double the suggest latency.
230		var (
231			status, clustersJSON   string
232			statusErr, clustersErr error
233			wg                     sync.WaitGroup
234		)
235		wg.Add(2)
236		go func() { defer wg.Done(); status, statusErr = runCLI("", "entire", "auth", "status") }()
237		go func() { defer wg.Done(); clustersJSON, clustersErr = runCLI("", "entire", "api", "/api/v1/clusters") }()
238		wg.Wait()
239		if statusErr != nil {
240			return suggestEntry{Error: statusErr.Error()}
241		}
242		if clustersErr != nil {
243			return suggestEntry{Error: clustersErr.Error()}
244		}
245	
246		slug := statusField(status, "Jurisdiction:")
247		loginHost := statusField(status, "Context:")
248		handle := strings.TrimPrefix(statusField(status, "User:"), "@")
249		if slug == "" || loginHost == "" || handle == "" {
250			return suggestEntry{Error: "could not parse `entire auth status` output (need Jurisdiction, Context, and User lines)"}
251		}
252		baseDomain := loginHost
253		if i := strings.Index(loginHost, ".auth."); i >= 0 {
254			baseDomain = loginHost[i+len(".auth."):]
255		}
256		var doc struct {
257			Clusters []struct {
258				Jurisdiction string `json:"jurisdiction"`
259				PublicURL    string `json:"publicUrl"`
260				IsDefault    bool   `json:"isDefault"`
261			} `json:"clusters"`
262		}
263		if err := json.Unmarshal([]byte(clustersJSON), &doc); err != nil {
264			return suggestEntry{Error: fmt.Sprintf("decode clusters: %v", err)}
265		}
266		remote := ""
267		for _, c := range doc.Clusters {
268			if c.Jurisdiction == slug && (remote == "" || c.IsDefault) {
269				remote = c.PublicURL
270			}
271		}
272		if remote == "" {
273			return suggestEntry{Error: fmt.Sprintf("no cluster in jurisdiction %q", slug)}
274		}
275	
276		repo := fmt.Sprintf("et/forgemark-%s/forgemark-target", handle)
277		return suggestEntry{
278			Target: &TargetSpec{
279				Name:         "entire-" + slug,
280				Remote:       remote,
281				Repos:        []string{repo},
282				TokenURL:     "https://" + loginHost + "/oauth/token",
283				Jurisdiction: "https://" + slug + "." + baseDomain,
284				SecretSource: "entire",
285			},
286			Note: fmt.Sprintf("repo %s must exist — FM_ENTIRE_NATIVE=1 scripts/compare-local.sh provisions it", repo),
287		}
288	}
289	
290	// statusField pulls the value after a "Label:" line prefix from the
291	// key-value block `entire auth status` prints.
292	func statusField(status, label string) string {
293		for _, line := range strings.Split(status, "\n") {
294			line = strings.TrimSpace(line)
295			if rest, ok := strings.CutPrefix(line, label); ok {
296				if fields := strings.Fields(rest); len(fields) > 0 {
297					return fields[0]
298				}
299			}
300		}
301		return ""
302	}
